import { test } from "node:test";
import assert from "node:assert/strict";
import { execFileSync } from "node:child_process";
import { readdirSync, readFileSync, statSync } from "node:fs";
import { join } from "node:path";
import { fileURLToPath } from "node:url";

/*
 * One icon set (docs/history/343-*): every icon is Solar, generated by scripts/build-icons.mjs into
 * src/components/icons — ONE FILE PER ICON so a page bundles only what it imports (a barrel put all 267 icons,
 * ~106 KB gzip, on every page). This guards: a new lucide (or other icon package) import, a barrel import, an import
 * of an icon/file that does not exist, and a hand edit / stale copy of the generated files.
 */

const ROOT = fileURLToPath(new URL("../..", import.meta.url));
const SRC = join(ROOT, "src");
const ICON_DIR = join(SRC, "components/icons");
const FACTORY = readFileSync(join(ICON_DIR, "icon.tsx"), "utf8");

function sourceFiles(dir: string): string[] {
  return readdirSync(dir).flatMap((name) => {
    const path = join(dir, name);
    if (statSync(path).isDirectory()) return sourceFiles(path);
    return /\.(tsx?|mjs)$/.test(name) ? [path] : [];
  });
}

const files = sourceFiles(SRC);
const rel = (path: string) => path.slice(ROOT.length);

test("hiçbir dosya lucide-react ya da başka bir ikon paketi import etmez", () => {
  const offenders = files.filter((path) =>
    /from\s+["'](lucide-react|@heroicons\/|react-icons|@phosphor-icons\/|@tabler\/icons)/.test(readFileSync(path, "utf8")),
  );
  assert.deepEqual(offenders.map(rel), []);
});

test("her ikon kendi dosyasından gelir ve o dosya o ikonu dışa verir (barrel yok)", () => {
  const problems: string[] = [];
  for (const path of files) {
    const text = readFileSync(path, "utf8");
    if (/from\s*["']@\/components\/icons["']/.test(text)) problems.push(`${rel(path)}: barrel import — ikonu kendi dosyasından al`);
    for (const m of text.matchAll(/import\s*(?:type\s*)?\{([^}]*)\}\s*from\s*["']@\/components\/icons\/([\w-]+)["']/g)) {
      let source = "";
      try {
        source = readFileSync(join(ICON_DIR, `${m[2]}.tsx`), "utf8");
      } catch {
        problems.push(`${rel(path)}: @/components/icons/${m[2]} yok`);
        continue;
      }
      for (const raw of m[1].split(",")) {
        const name = raw.replace(/^\s*type\s+/, "").split(/\s+as\s+/)[0].trim();
        if (name && !new RegExp(`export (?:const|type|interface|function) ${name}\\b`).test(source)) {
          problems.push(`${rel(path)}: ${m[2]} → ${name} yok`);
        }
      }
    }
  }
  assert.deepEqual(problems, [], "eksik ikonu scripts/build-icons.mjs ICON_MAP'e ekleyip betiği çalıştır");
});

test("üretilen ikon dosyaları üreticiyle güncel (elle düzenlenmemiş)", () => {
  // Needs the @iconify-json/solar dev dependency (present after `npm ci`).
  const out = execFileSync(process.execPath, [join(ROOT, "scripts/build-icons.mjs"), "--check"], { encoding: "utf8" });
  assert.match(out, /icons up to date/);
});

test("ikon dosyaları Solar atfını ve lisansını taşır", () => {
  assert.match(FACTORY, /Solar Icon Set by 480 Design/);
  assert.match(FACTORY, /CC BY 4\.0/);
  assert.match(readFileSync(join(ICON_DIR, "heart.tsx"), "utf8"), /solar:heart-bold-duotone — Solar Icon Set by 480 Design.*CC BY 4\.0/);
});
